B.ckD={"\u0627\u0644\u0625\u064a\u0645\u064a\u0644 \u0623\u0648 \u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631 \u063a\u0644\u0637":0,"\u0645\u0641\u064a\u0634 \u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0633\u064a\u0631\u0641\u0631. \u062c\u0631\u0628 \u062a\u0627\u0646\u064a.":1,[u.oi]:2,[u.bA]:3,"\u0627\u0644\u0625\u064a\u0645\u064a\u0644":4,"\u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631":5,"\u0644\u062d\u0638\u0629...":6,"\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644":7,"\u0646\u0633\u064a\u062a \u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631\u061f":8,[u.jB]:9,[u.a6]:10,"\u0643\u0644\u0645\u062a\u064a\u0646 \u0627\u0644\u0633\u0631 \u0645\u0634 \u0632\u064a \u0628\u0639\u0636":11,"\u0623\u0647\u0644\u064b\u0627 \u0628\u064a\u0643! \u0627\u0639\u0645\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0631 \u0628\u062a\u0627\u0639\u062a\u0643":12,"\u0627\u0639\u0645\u0644 \u0643\u0644\u0645\u0629 \u0633\u0631 \u062c\u062f\u064a\u062f\u0629":13,"\u0627\u0644\u0627\u0633\u0645 \u0628\u0627\u0644\u0643\u0627\u0645\u0644":14,"\u0627\u0643\u062a\u0628\u0647\u0627 \u062a\u0627\u0646\u064a":15,"\u062d\u0641\u0638 \u0648\u0627\u0644\u062f\u062e\u0648\u0644":16,[u.cQ]:17,"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0625\u0646\u0634\u0627\u0626\u064a\u0629":18}
